  function colorFromHex(hex) {
    var c = new SolidColor();
    c.rgb.red = parseInt(hex.substr(1, 2), 16);
    c.rgb.green = parseInt(hex.substr(3, 2), 16);
    c.rgb.blue = parseInt(hex.substr(5, 2), 16);
    return c;
  }

